#include <stdio.h>

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int g[105][105];
    int costA = 0; // Caso A: (i + j) par -> par, (i + j) ímpar -> ímpar
    int costB = 0; // Caso B: (i + j) par -> ímpar, (i + j) ímpar -> par

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            scanf("%d", &g[i][j]);
            int desired_parity_A = (i + j) % 2; // se (i+j) é par (0), queremos par (0). Se ímpar (1), queremos ímpar (1).
            if ((g[i][j] % 2) != desired_parity_A) {
                costA++;
            } else {
                costB++;
            }
        }
    }

    int chooseA = (costA <= costB);
    printf("%d\n", chooseA ? costA : costB);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int desired_parity = chooseA ? ((i + j) % 2) : (1 - (i + j) % 2);
            int val = g[i][j];
            if ((val % 2) != desired_parity) {
                val++;
            }
            printf("%d%c", val, (j == m - 1) ? '\n' : ' ');
        }
    }

    return 0;
}
